mapper.select:
select *
from wms_statistics_inbound
where
bool_delete_enum = 0 and
DATE_FORMAT(NOW(), '%Y%m') = DATE_FORMAT(create_time, '%Y%m')
and statistics_id = #{id}
and receipt_type = #{type}
and basic_class = #{mat.basicClass}
and bool_party_a = #{mat.boolPartyA}
and classify_id = #{mat.classifyId}
and workshop_id = #{mat.workshopId}
AND warehouse_id = #{mat.warehouseId}
AND specification = #{mat.specification}

    AND material_is_whole = #{mat.materialIsWhole}


    AND tax_rate = #{mat.taxRate}


    AND tax_rate is null


    AND length = #{mat.length}


    AND length is null


    AND width = #{mat.width}


    AND width is null


    AND thickness = #{mat.thickness}


    AND thickness is null


    AND unit_net = #{mat.unitNet}


    AND unit_net is null


    AND project_id = #{mat.projectId}


    AND project_id is null


    AND heat_no_and_batch_no = #{mat.heatNoAndBatchNo}


    AND heat_no_and_batch_no is null


    AND brand = #{mat.brand}


    AND brand is null


    AND color = #{mat.color}


    AND color is null

select wsi.*, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, wc.name classifyName, ww.id wwId, ww.name wwName from wms_statistics_inbound wsi left join contract_project p on p.id = wsi.project_id left join wms_workshop mbf on wsi.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wsi.warehouse_id left join wms_classification wc on wsi.classify_id = wc.id left join plan_monomer pm on pm.id = wsi.monomer_id left join plan_area pa on pa.id = wsi.area_id where wsi.bool_delete_enum = 0
and COALESCE(wsi.real_time, CASE WHEN wsi.receipt_type = 15 THEN (SELECT t.review_time FROM wms_transfer t WHERE t.id = wsi.receipt_id AND t.review_status = 2 AND t.bool_delete_enum = 0) END) > #{times.startTime}
and COALESCE(wsi.real_time, CASE WHEN wsi.receipt_type = 15 THEN (SELECT t.review_time FROM wms_transfer t WHERE t.id = wsi.receipt_id AND t.review_status = 2 AND t.bool_delete_enum = 0) END) < #{times.endTime}
and wsi.statistics_id in
#{item}
and wsi.receipt_type in
#{item}

