and COALESCE(wsi.real_time, CASE WHEN wsi.receipt_type = 15 THEN (SELECT t.review_time FROM wms_transfer t WHERE t.id = wsi.receipt_id AND t.review_status = 2 AND t.bool_delete_enum = 0) END) < #{times.endTime}
