select wsi.*, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, wc.name classifyName, ww.id wwId, ww.name wwName from wms_statistics_inbound wsi left join contract_project p on p.id = wsi.project_id left join wms_workshop mbf on wsi.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wsi.warehouse_id left join wms_classification wc on wsi.classify_id = wc.id left join plan_monomer pm on pm.id = wsi.monomer_id left join plan_area pa on pa.id = wsi.area_id where wsi.bool_delete_enum = 0 and wsi.create_time > #{times.startTime} and wsi.create_time < #{times.endTime}
and wsi.statistics_id in
#{item}

select SUM(amount_excluding_vat)
from wms_statistics_inbound wsi
where bool_delete_enum = 0

    and COALESCE(wsi.real_time, CASE WHEN wsi.receipt_type = 15 THEN (SELECT t.review_time FROM wms_transfer t WHERE t.id = wsi.receipt_id AND t.review_status = 2 AND t.bool_delete_enum = 0) END) > #{times.startTime}


    and COALESCE(wsi.real_time, CASE WHEN wsi.receipt_type = 15 THEN (SELECT t.review_time FROM wms_transfer t WHERE t.id = wsi.receipt_id AND t.review_status = 2 AND t.bool_delete_enum = 0) END) < #{times.endTime}

select SUM(amount_excluding_vat)
from wms_statistics_inbound
where bool_delete_enum = 0
    and  create_time > #{times.startTime}
    and  create_time < #{times.endTime}

    and receipt_type in
    
